package com.together.couple;
import android.app.*;import android.content.*;import android.os.*;import android.graphics.Color;import android.view.Gravity;import android.widget.*;
public class IncomingCallActivity extends Activity{
private boolean listening=false;private final BroadcastReceiver ended=new BroadcastReceiver(){@Override public void onReceive(Context context,Intent intent){if(java.util.Objects.equals(intent.getStringExtra("id"),getIntent().getStringExtra("id")))finish();}};
private final Handler handler=new Handler(Looper.getMainLooper());private final Runnable timeout=()->finish();
@Override public void onCreate(Bundle state){super.onCreate(state);if(Build.VERSION.SDK_INT>=27){setShowWhenLocked(true);setTurnScreenOn(true);}long expires=getIntent().getLongExtra("expires",0);if(expires<=System.currentTimeMillis()){finish();return;}handler.postDelayed(timeout,expires-System.currentTimeMillis());String id=getIntent().getStringExtra("id");IntentFilter filter=new IntentFilter(getPackageName()+".CALL_ENDED");if(Build.VERSION.SDK_INT>=33)registerReceiver(ended,filter,Context.RECEIVER_NOT_EXPORTED);else registerReceiver(ended,filter);listening=true;
LinearLayout layout=new LinearLayout(this);layout.setOrientation(LinearLayout.VERTICAL);layout.setGravity(Gravity.CENTER);layout.setPadding(40,40,40,40);layout.setBackgroundColor(Color.rgb(255,250,245));TextView name=new TextView(this);name.setText(getIntent().getStringExtra("name"));name.setTextSize(28);name.setTextColor(Color.rgb(51,38,56));layout.addView(name);TextView label=new TextView(this);label.setText("Incoming "+getIntent().getStringExtra("kind")+" call");layout.addView(label);Button answer=new Button(this);answer.setText("Answer");answer.setOnClickListener(v->{((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).cancel(id.hashCode());startActivity(new Intent(this,MainActivity.class).putExtra("call_id",id).putExtra("call_action","answer"));finish();});layout.addView(answer);Button decline=new Button(this);decline.setText("Decline");decline.setOnClickListener(v->{sendBroadcast(new Intent(this,CallDeclineReceiver.class).putExtra("id",id));finish();});layout.addView(decline);setContentView(layout);}
@Override protected void onDestroy(){handler.removeCallbacks(timeout);if(listening)unregisterReceiver(ended);super.onDestroy();}
}